-- Gridfinity-compatible bin generator.
-- The sloped parts are loaded from STLs with exact 45 degree faces, generated by
-- tools/gen-gridfinity-meshes.py: the locating foot, the stacking lip, the
-- support under the lip and the hollow UltraLight base. The plugin API cannot
-- build a sloped mesh or stretch a loaded one, so lip and support are tiled from
-- corner and straight pieces that fit every bin size.

info = {
    id = "dev.leotrax3d.box-generator",
    type = "project.plugin",
    title = "Gridfinity Bin Generator",
    menu = "Generators/Gridfinity Bin",
    params = {
        {name = "units_x",       label = "Grid Units X",            type = "int",    default = 1},
        {name = "units_y",       label = "Grid Units Y",            type = "int",    default = 1},
        {name = "height_units",  label = "Height Units (7 mm)",     type = "int",    default = 3},
        {name = "ultralight",    label = "UltraLight Hollow Base",  type = "bool",   default = true},
        {name = "floor_th",      label = "Floor Thickness [mm]",    type = "float",  default = 1.2},
        {name = "columns",       label = "Compartments Across",     type = "int",    default = 1},
        {name = "rows",          label = "Compartments Deep",       type = "int",    default = 1},
        {name = "divider_th",    label = "Divider Thickness [mm]",  type = "float",  default = 1.2},
        {name = "magnet_holes",  label = "6x2 mm Magnet Pockets",   type = "bool",   default = false},
        {name = "stacking_lip",  label = "Stacking Lip",            type = "bool",   default = true},
        {name = "label",         label = "Front Label",             type = "string", default = ""}
    }
}

local GRID, XY_CLEARANCE, HEIGHT_UNIT = 42.0, 0.5, 7.0
local BASE_HEIGHT = 4.75
local FOOT_TOP, FOOT_RADIUS = 41.5, 3.75
-- The wall is fixed, as in the published profile: the support under the lip and
-- the hollow base are generated for it.
local WALL = 1.2
-- The lip's inner edge is 2.6 mm in. The support rises from the wall to it at
-- 45 degrees and ends 0.6 mm below the lip.
local LIP_BACKING, SUPPORT_BELOW_LIP = 2.6, 2.0
-- UltraLight base: the pocket ends where its slope meets the wall. Between grid
-- cells the body bottom keeps a floor of its own, 1.0 mm above the 4.75 mm base.
local POCKET_FLOOR, POCKET_TOP, CELL_FLOOR_TOP = 1.0, 4.96, 5.75
local MAGNET_RADIUS, MAGNET_DEPTH, MAGNET_OFFSET = 3.25, 2.4, 13.0
local BREAK = 0.2

local FOOT_STL, POCKET_STL = "gridfinity_foot.stl", "gridfinity_pocket.stl"
local LIP = {corner = "gridfinity_lip_corner.stl", long = "gridfinity_lip_42.stl",
             short = "gridfinity_lip_34.stl", inset = 0}
local SUPPORT = {corner = "gridfinity_support_corner.stl", long = "gridfinity_support_42.stl",
                 short = "gridfinity_support_34.stl", inset = WALL, negative = true}

local function clamp(value, low, high)
    return math.max(low, math.min(high, value))
end

local function integer(value, low, high)
    return math.floor(clamp(value, low, high) + 0.5)
end

--- Places a loaded mesh rotated about Z by a multiple of 90 degrees, so that the
-- local point `anchor` lands on `target`. The slicer rotates each volume about its
-- own origin before translating it.
local function place_rotated(builder, mesh, angle, anchor, target, vtype)
    local c = math.floor(math.cos(math.rad(angle)) + 0.5)
    local s = math.floor(math.sin(math.rad(angle)) + 0.5)
    builder:add {
        mesh = mesh,
        rotate = angle ~= 0 and {z = angle} or nil,
        x = target.x - (anchor.x * c - anchor.y * s),
        y = target.y - (anchor.x * s + anchor.y * c),
        z = target.z - anchor.z,
        type = vtype
    }
end

--- A ring of pieces around the bin -- the stacking lip or the support under it --
-- walked counter-clockwise from the front-left corner. Each side of n units is
-- 42 n - 8 mm between its corners: n - 1 pieces of 42 mm and one of 34 mm.
-- Straight pieces run along their local +X with the wall inwards along +Y,
-- starting `inset` mm in from the outer face; the corner is the front-left
-- quarter about its arc centre, which is its bounds' maximum corner.
local function add_ring(builder, set, outer_w, outer_d, ux, uy, z0)
    local corner = api.load_stl(set.corner)
    local long, short = api.load_stl(set.long), api.load_stl(set.short)
    local cb, lb, sb = corner:bounds(), long:bounds(), short:bounds()
    local vtype = set.negative and VolumeType.Negative or nil
    local r = FOOT_RADIUS

    local sides = {
        {angle = 0,   units = ux, start = {x = r, y = 0},                 step = {x = 1, y = 0}},
        {angle = 90,  units = uy, start = {x = outer_w, y = r},           step = {x = 0, y = 1}},
        {angle = 180, units = ux, start = {x = outer_w - r, y = outer_d}, step = {x = -1, y = 0}},
        {angle = 270, units = uy, start = {x = 0, y = outer_d - r},       step = {x = 0, y = -1}}
    }
    local corners = {
        {angle = 0,   x = r,           y = r},
        {angle = 90,  x = outer_w - r, y = r},
        {angle = 180, x = outer_w - r, y = outer_d - r},
        {angle = 270, x = r,           y = outer_d - r}
    }

    for _, side in ipairs(sides) do
        local along = 0
        for piece = 1, side.units do
            local mesh, b = long, lb
            if piece == side.units then mesh, b = short, sb end
            place_rotated(builder, mesh, side.angle,
                {x = b.min_x, y = b.min_y - set.inset, z = b.min_z},
                {x = side.start.x + side.step.x * along,
                 y = side.start.y + side.step.y * along, z = z0}, vtype)
            along = along + (b.max_x - b.min_x)
        end
    end
    for _, c in ipairs(corners) do
        place_rotated(builder, corner, c.angle,
            {x = cb.max_x, y = cb.max_y, z = cb.min_z}, {x = c.x, y = c.y, z = z0}, vtype)
    end
end

--- Places one copy of a loaded mesh centred on each grid cell, bottom at z0.
local function add_per_cell(builder, mesh, ux, uy, z0, vtype)
    local b = mesh:bounds()
    for gx = 0, ux - 1 do
        for gy = 0, uy - 1 do
            local cx, cy = gx * GRID + FOOT_TOP * 0.5, gy * GRID + FOOT_TOP * 0.5
            builder:add {
                mesh = mesh,
                x = cx - (b.min_x + b.max_x) * 0.5,
                y = cy - (b.min_y + b.max_y) * 0.5,
                z = z0 - b.min_z,
                type = vtype
            }
        end
    end
end

function execute(opts)
    local shapes = require('shapes')
    local labels = require('labels')

    local ux = integer(opts.units_x, 1, 6)
    local uy = integer(opts.units_y, 1, 6)
    local hu = integer(opts.height_units, 1, 12)
    local floor_th = clamp(opts.floor_th, 0.8, 4)
    local divider = clamp(opts.divider_th, 0.8, 4)
    local ow, od = ux * GRID - XY_CLEARANCE, uy * GRID - XY_CLEARANCE
    local max_columns = math.max(1, math.floor((ow - 2 * WALL) / (2 * divider)))
    local max_rows = math.max(1, math.floor((od - 2 * WALL) / (2 * divider)))
    local columns = integer(opts.columns, 1, math.min(20, max_columns))
    local rows = integer(opts.rows, 1, math.min(20, max_rows))
    local single = columns == 1 and rows == 1
    local bin = shapes.builder()

    -- The hollow base needs one open space: dividers would have to reach into the
    -- pockets, and magnets need a solid foot. A multi-cell bin also needs room for
    -- the floor between its cells below the lip support, so at least 2 units.
    local ultralight = opts.ultralight and single and not opts.magnet_holes
                       and (ux * uy == 1 or hu >= 2)
    -- A solid base needs room for its floor and some cavity above it.
    local body_top = hu * HEIGHT_UNIT
    if not ultralight then
        body_top = math.max(body_top, BASE_HEIGHT + floor_th + 2)
    end
    local body_h = body_top - BASE_HEIGHT

    add_per_cell(bin, api.load_stl(FOOT_STL), ux, uy, 0)
    bin:add_slab(
        shapes.rounded_slab(ow, od, body_h, FOOT_RADIUS),
        {x = 0, y = 0, z = BASE_HEIGHT}
    )

    local cavity_z = BASE_HEIGHT + floor_th
    if ultralight then
        -- Each foot hollowed to a 1.0 mm shell over a 1.0 mm floor. In a single
        -- cell the pocket opens straight into the cavity; between cells the body
        -- keeps a floor, so each pocket is extended up through it.
        add_per_cell(bin, api.load_stl(POCKET_STL), ux, uy, POCKET_FLOOR, VolumeType.Negative)
        cavity_z = POCKET_TOP
        if ux * uy > 1 then
            cavity_z = CELL_FLOOR_TOP
            local size = FOOT_TOP - 2 * WALL
            for gx = 0, ux - 1 do
                for gy = 0, uy - 1 do
                    bin:add_slab(
                        shapes.rounded_slab(size, size, CELL_FLOOR_TOP - POCKET_TOP,
                                            FOOT_RADIUS - WALL),
                        {x = gx * GRID + WALL, y = gy * GRID + WALL, z = POCKET_TOP},
                        VolumeType.Negative
                    )
                end
            end
        end
    end

    local support_z = body_top - SUPPORT_BELOW_LIP
    if single and opts.stacking_lip and support_z >= cavity_z then
        -- One open cavity under a lip: carve the 45 degree support instead of
        -- leaving the lip's inner edge overhanging. Below the support the cavity
        -- reaches the wall; above it only the area inside the lip backing is open.
        if support_z > cavity_z then
            bin:add_slab(
                shapes.rounded_slab(ow - 2 * WALL, od - 2 * WALL, support_z - cavity_z,
                                    FOOT_RADIUS - WALL),
                {x = WALL, y = WALL, z = cavity_z}, VolumeType.Negative
            )
        end
        bin:add_slab(
            shapes.rounded_slab(ow - 2 * LIP_BACKING, od - 2 * LIP_BACKING,
                                body_top - cavity_z, FOOT_RADIUS - LIP_BACKING),
            {x = LIP_BACKING, y = LIP_BACKING, z = cavity_z}, VolumeType.Negative
        )
        add_ring(bin, SUPPORT, ow, od, ux, uy, support_z)
    else
        -- Each compartment is its own negative pocket. The material between the
        -- pockets is therefore a divider even after PrusaSlicer sorts volume types.
        local usable_w = ow - 2 * WALL - (columns - 1) * divider
        local usable_d = od - 2 * WALL - (rows - 1) * divider
        local cell_w, cell_d = usable_w / columns, usable_d / rows
        local cavity_h = body_top - cavity_z
        for col = 0, columns - 1 do
            for row = 0, rows - 1 do
                local x = WALL + col * (cell_w + divider)
                local y = WALL + row * (cell_d + divider)
                bin:add_slab(
                    shapes.rounded_slab(cell_w, cell_d, cavity_h,
                                        math.min(2.8, cell_w * 0.25, cell_d * 0.25)),
                    {x = x, y = y, z = cavity_z}, VolumeType.Negative
                )
            end
        end
    end

    if opts.magnet_holes then
        for gx = 0, ux - 1 do
            for gy = 0, uy - 1 do
                local cx, cy = gx * GRID + FOOT_TOP * 0.5, gy * GRID + FOOT_TOP * 0.5
                for _, dx in ipairs({-MAGNET_OFFSET, MAGNET_OFFSET}) do
                    for _, dy in ipairs({-MAGNET_OFFSET, MAGNET_OFFSET}) do
                        local hole = shapes.cylinder_at(MAGNET_RADIUS, MAGNET_DEPTH + BREAK,
                                                        cx + dx, cy + dy, -BREAK)
                        hole.type = VolumeType.Negative
                        bin:add(hole)
                    end
                end
            end
        end
    end

    if opts.stacking_lip then
        add_ring(bin, LIP, ow, od, ux, uy, body_top)
    end

    if opts.label ~= "" then
        bin:add_definition(labels.front_label {
            text = opts.label,
            center_x = ow * 0.5,
            center_z = BASE_HEIGHT + body_h * 0.55,
            face_y = 0,
            size = math.min(8, math.max(3, body_h * 0.25))
        })
    end

    bin:emit({x = 0, y = 0, z = 0})
end
